import { describe, expect, it, vi } from 'vitest'

vi.mock('next/cache', () => ({ revalidatePath: vi.fn(), revalidateTag: vi.fn() }))
vi.mock('@payloadcms/next/css', () => ({}))

describe('download duration', () => {
  // GET /api/documents/:id/file is a Payload endpoint served by this catch-all route. The file
  // is marked as generated by Payload; this test catches the export being lost on regeneration.
  it('lets Payload API routes, including file downloads, run up to the Vercel Hobby limit', async () => {
    const route: { maxDuration?: unknown } = await import('@/app/(payload)/api/[...slug]/route')
    expect(route.maxDuration).toBe(300)
  }, 60_000)
})
